settings.custom_code:
{% assign comparison = product.metafields.custom.iron_comparison.value %}

{% if comparison %}
  {% assign cards = comparison.iron_comparison_card.value %}
  {% if cards == blank %}
    {% assign cards = comparison.iron_comparison_card %}
  {% endif %}

  <style>
    .iron-comparison { margin-top: 48px; }

    /* Horizontal scroll container */
    .iron-comparison__scroll {
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
    }

    .iron-comparison__scroll::-webkit-scrollbar { height: 8px; }
    .iron-comparison__scroll::-webkit-scrollbar-thumb { background: #cfcfcf; border-radius: 999px; }
    .iron-comparison__scroll::-webkit-scrollbar-track { background: #f2f2f2; }

    /* Scrollable row */
    .iron-comparison__grid {
      display: flex;
      gap: 24px;
      padding-bottom: 8px;
    }

    .iron-comparison__card {
      flex: 0 0 300px;
      display: flex;
      flex-direction: column;
    }

    .iron-comparison__title-image {
      background: #000000;
      padding: 16px;
      display: flex;
      justify-content: center;
      align-items: center;
    }

    .iron-comparison__product-image {
      background: #EAEAEA;
      padding: 24px;
      display: flex;
      justify-content: center;
      align-items: center;
    }

    .iron-comparison__title-image img,
    .iron-comparison__product-image img {
      max-width: 100%;
      height: auto !important;
      object-fit: contain !important;
      display: block;
    }

    /* Reduce title image size by 50% */
    .iron-comparison__title-image img {
      max-width: 50%;
    }

    .iron-comparison__description {
      margin-top: 16px;
      font-size: 14px;
      line-height: 1.5;
    }

    .iron-comparison__ratings {
      margin-top: 20px;
      border-top: 1px solid #e5e5e5;
    }

    .iron-comparison__rating-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 14px 22px;
      border-bottom: 1px solid #e5e5e5;
      font-size: 13px;
      text-transform: uppercase;
      letter-spacing: 0.04em;
      column-gap: 12px;
    }

    /* Alternating background */
    .iron-comparison__rating-row:nth-child(odd) { background: #ffffff; }
    .iron-comparison__rating-row:nth-child(even) { background: #EAEAEA; }

    .iron-comparison__rating-label {
      font-weight: 600;
      flex: 0 0 55%;
      text-align: left;
    }

    .iron-comparison__rating-value {
      flex: 0 0 45%;
      text-align: right;
      padding-right: 6px;
      white-space: nowrap;
    }
  </style>

  <section class="iron-comparison">
    <div class="iron-comparison__scroll">
      <div class="iron-comparison__grid">

        {% for card in cards %}
          <div class="iron-comparison__card">

            {% if card.title_image %}
              <div class="iron-comparison__title-image">
                {{ card.title_image | image_url: width: 600 | image_tag: loading: 'lazy' }}
              </div>
            {% endif %}

            {% if card.product_image %}
              <div class="iron-comparison__product-image">
                {{ card.product_image | image_url: width: 900 | image_tag: loading: 'lazy' }}
              </div>
            {% endif %}

            {% if card.description != blank %}
              <div class="iron-comparison__description">
                {{ card.description }}
              </div>
            {% endif %}

            <div class="iron-comparison__ratings">
              <div class="iron-comparison__rating-row">
                <span class="iron-comparison__rating-label">Handicap</span>
                <span class="iron-comparison__rating-value">{{ card.handicap }}</span>
              </div>

              <div class="iron-comparison__rating-row">
                <span class="iron-comparison__rating-label">Forgiveness</span>
                <span class="iron-comparison__rating-value">{{ card.forgiveness }}</span>
              </div>

              <div class="iron-comparison__rating-row">
                <span class="iron-comparison__rating-label">Trajectory</span>
                <span class="iron-comparison__rating-value">{{ card.trajectory }}</span>
              </div>

              <div class="iron-comparison__rating-row">
                <span class="iron-comparison__rating-label">Workability</span>
                <span class="iron-comparison__rating-value">{{ card.workability }}</span>
              </div>

              <div class="iron-comparison__rating-row">
                <span class="iron-comparison__rating-label">Distance</span>
                <span class="iron-comparison__rating-value">{{ card.distance }}</span>
              </div>
            </div>

          </div>
        {% endfor %}

      </div>
    </div>
  </section>
{% endif %}
